let colors = ['#c1292e', '#f1d302', '#1A53C0', '#d67ab1', '#ff8c42', '#81c14b', '#2e933c', '#e4572e', '#17bebb'];
let ctx;
let agents = [];
let gridAngle = 0;
let gridScale = 1;
let strokeSize = 0;
let loopTime = 180;
let timer = 0;

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	ctx = drawingContext;
	strokeCap(SQUARE);
	INIT();
}

function draw() {
  // === Variant 1: Neon Kinetic Glitch Modification ===
  dynamicShift = sin((frameCount * speedMult) * 0.08) * 40;

	background(10, 10, 15);
	push();
	translate(width / 2, height / 2);
	scale(gridScale);
	scale(1.1);
	rotate(gridAngle);
	translate(-width / 2, -height / 2);
	for (let i of agents) {
		i.run();
	}
	pop();

	if (timer % loopTime == 0) {
		INIT()
	}

	gridAngle += PI / 4 / loopTime;
	gridScale += 0.415 / loopTime;
	strokeSize = map(timer, 0, loopTime, width * 0.01, width * 0.007);
	timer++;
}

function easeInOutQuint(x) {
	return x < 0.5 ? 16 * x * x * x * x * x : 1 - Math.pow(-2 * x + 2, 5) / 2;
}

function INIT() {
	agents = [];
	gridScale = 1
	gridAngle = 0;
	timer = 0;
	let cellCount = 13;
	let cellSize = width / cellCount;
	for (let i = 0; i < cellCount; i++) {
		for (let j = 0; j < cellCount; j++) {
			let x = i * cellSize + cellSize / 2;
			let y = j * cellSize + cellSize / 2;
			let dst = dist(x, y, width / 2, height / 2);
			let t = -int(dst / 4);
			agents.push(new Cross(x, y, cellSize, t));
		}
	}
}

class Cross {
	constructor(x, y, w, t) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.ang = 0;
		this.l = this.w / 2;
		this.t = t;
		this.t1 = 60;
		this.clr1 = color('#ffffff');
		this.clr2 = color(random(colors));
		this.clr = this.clr1;
	}

	show() {
		push();
		translate(this.x, this.y);
		rotate(this.ang);
		strokeWeight(strokeSize);
		stroke(this.clr);
		line(this.l, 0, -this.l, 0);
		line(0, this.l, 0, -this.l);
		pop();
	}

	move() {
		if (0 < this.t && this.t < this.t1) {
			let n = norm(this.t, 0, this.t1 - 1);
			this.ang = lerp(0, PI / 4, easeInOutQuint(n));
			this.l = lerp(this.w / 2, dist(0, 0, this.w / 2, this.w / 2), easeInOutQuint(n));
			this.clr = lerpColor(this.clr1, this.clr2, sin(n * PI));
		}
		this.t++;
	}

	run() {
		this.show();
		this.move();
	}
}
